import dpbequ = require( './index' );

var AB = new Float64Array( 6 );
var S = new Float64Array( 3 );
var SCOND = new Float64Array( 1 );
var AMAX = new Float64Array( 1 );

dpbequ( 'row-major', 'upper', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 'row-major', 'lower', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 'row-major', 121, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 'row-major', 122, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 'column-major', 'upper', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 'column-major', 'lower', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 'column-major', 121, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 'column-major', 122, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 101, 'upper', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 101, 'lower', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 101, 121, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 101, 122, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 102, 'upper', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 102, 'lower', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 102, 121, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ( 102, 122, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectType number
dpbequ.ndarray( 'upper', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectType number
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectType number
dpbequ.ndarray( 121, 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectType number
dpbequ.ndarray( 122, 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectType number

dpbequ(  ); // $ExpectError
dpbequ( 'row-major' ); // $ExpectError
dpbequ( 'row-major', 'lower' ); // $ExpectError
dpbequ( 'row-major', 'lower', 3 ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1 ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB, 3 ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB, 3, S ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB, 3, S, SCOND ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB, 3, S, SCOND, AMAX, 0 ); // $ExpectError
dpbequ( 'invalid', 'lower', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectError
dpbequ( 'row-major', 'invalid', 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectError
dpbequ( 'row-major', 'lower', 'invalid', 1, AB, 3, S, SCOND, AMAX ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 'invalid', AB, 3, S, SCOND, AMAX ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, 'invalid', 3, S, SCOND, AMAX ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB, 'invalid', S, SCOND, AMAX ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB, 3, 'invalid', SCOND, AMAX ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB, 3, S, 'invalid', AMAX ); // $ExpectError
dpbequ( 'row-major', 'lower', 3, 1, AB, 3, S, SCOND, 'invalid' ); // $ExpectError
dpbequ.ndarray(  ); // $ExpectError
dpbequ.ndarray( 'lower' ); // $ExpectError
dpbequ.ndarray( 'lower', 3 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0, 0 ); // $ExpectError
dpbequ.ndarray( 'invalid', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 'invalid', 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 'invalid', AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, 'invalid', 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 'invalid', 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 'invalid', 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 'invalid', S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, 'invalid', 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 'invalid', 0, SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 'invalid', SCOND, 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, 'invalid', 0, AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 'invalid', AMAX, 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, 'invalid', 0 ); // $ExpectError
dpbequ.ndarray( 'lower', 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 'invalid' ); // $ExpectError
dpbequ( 'row-major', 0, 3, 1, AB, 3, S, SCOND, AMAX ); // $ExpectError
dpbequ.ndarray( 0, 3, 1, AB, 3, 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 ); // $ExpectError
